const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const year = 2023;
  const startDate = ee.Date.fromYMD(year, 1, 1);
  const endDate = ee.Date.fromYMD(year, 12, 31);

  // Define Quebec geometry
  const countries = ee.FeatureCollection('FAO/GAUL/2015/level1');
  let quebec = countries.filter(ee.Filter.eq('ADM1_NAME', 'Quebec'));

  if (quebec.size().getInfo() === 0) {
    console.log("Error: Could not find Quebec in the administrative boundaries dataset.");
    console.log("D");
    return;
  }
  quebec = quebec.first().geometry(); // Get the geometry of Quebec

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('MODIS/051/MCD64A1')
    .filterDate(startDate, endDate)
    .filterBounds(quebec);

  const collectionSize = await collection.size().getInfo();
  console.log(`MCD64A1 images for ${year}: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No MODIS MCD64A1 data found for Quebec in 2023.");
    console.log("C1");
    return;
  }

  // 3. Processing
  // Select the 'BurnDate' band. Pixels with BurnDate > 0 indicate a burn.
  // The value is the day of the year, so 0 means no burn.
  const burnedAreaImage = collection.select('BurnDate')
    .map(function(image) {
      // Create a binary mask where 1 indicates burned, 0 indicates unburned.
      const burnedMask = image.gt(0);
      // Multiply pixel area by the mask to get area of burned pixels.
      return ee.Image.pixelArea().updateMask(burnedMask).rename('burned_area');
    })
    .mosaic(); // Mosaic all images to get a single image of burned area.

  // Calculate total number of valid (burned) pixels to detect C2
  const pixelCount = await burnedAreaImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: quebec,
    scale: 500, // MCD64A1 resolution is 500m
    maxPixels: 1e9
  }).get('burned_area').getInfo();

  console.log(`Valid burned pixels after masking: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid burned pixels found for Quebec after processing.");
    console.log("C2");
    return;
  }

  // 4. Calculation
  const totalBurnedSqMeters = await burnedAreaImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: quebec,
    scale: 500, // MCD64A1 resolution is 500m
    maxPixels: 1e9
  }).get('burned_area').getInfo();

  if (totalBurnedSqMeters === null || isNaN(totalBurnedSqMeters)) {
    console.log("Calculation of total burned area failed.");
    console.log("C3");
    return;
  }

  const totalBurnedHectares = totalBurnedSqMeters / 10000; // Convert square meters to hectares
  const thresholdHectares = 0.8 * 1000000; // 0.8 million hectares

  console.log(`Total burned area in Quebec in ${year}: ${totalBurnedHectares.toFixed(2)} hectares.`);

  // 5. Validation & Final Answer
  if (totalBurnedHectares > thresholdHectares) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

